package com.example.kitsune.data.entity

import androidx.room.Entity
import androidx.room.ForeignKey
import androidx.room.Index
import androidx.room.PrimaryKey

/**
 * Representation of a discovered chapter archive indexed in the local database.
 * Filesystem remains the single source of truth.
 *
 * @param id Internal unique identifier generated by Room.
 * @param comicId Foreign key to parent [ComicEntity].
 * @param relativePath Relative archive path under the root (e.g. "Comics/One Piece/Chapter 1.cbz").
 * @param chapterNumber Numeric identifier parsed from the chapter file name.
 * @param displayName Original file name on filesystem (e.g. "Chapter 1.cbz").
 * @param pageCount Number of valid image pages indexed by [com.example.kitsune.scanner.CbzCataloger].
 * @param fileSize Size of the CBZ archive in bytes, if available.
 * @param lastModifiedAt Last modified timestamp of the CBZ archive from filesystem metadata.
 * @param isValid Flag indicating whether the chapter archive is valid and readable.
 */
@Entity(
    tableName = "chapters",
    foreignKeys = [
        ForeignKey(
            entity = ComicEntity::class,
            parentColumns = ["id"],
            childColumns = ["comicId"],
            onDelete = ForeignKey.CASCADE
        )
    ],
    indices = [
        Index(value = ["comicId", "chapterNumber"]),
        Index(value = ["comicId", "relativePath"], unique = true)
    ]
)
data class ChapterEntity(
    @PrimaryKey(autoGenerate = true)
    val id: Long = 0,
    val comicId: Long,
    val relativePath: String,
    val chapterNumber: Int,
    val displayName: String,
    val pageCount: Int,
    val fileSize: Long? = null,
    val lastModifiedAt: Long? = null,
    val isValid: Boolean = true
)

